const HOSTS=['cinemana.shabakaty.com','cinemana.shabakaty.cc'];
const CACHE=new Map();
const UA='Cinemana-Stremio-Worker/1.0';
const json=(x,status=200)=>new Response(JSON.stringify(x),{status,headers:{'content-type':'application/json; charset=utf-8','access-control-allow-origin':'*','cache-control':'public, max-age=120'}});
const text=(x,status=200)=>new Response(String(x),{status,headers:{'content-type':'text/plain; charset=utf-8','access-control-allow-origin':'*'}});
const asArray=v=>Array.isArray(v)?v:Array.isArray(v?.data)?v.data:Array.isArray(v?.content)?v.content:Array.isArray(v?.videos)?v.videos:[];
const clean=v=>String(v||'').toLowerCase().normalize('NFKD').replace(/[\u0300-\u036f\u064B-\u065F\u0670]/g,'').replace(/&/g,' and ').replace(/[^a-z0-9\u0600-\u06ff]+/g,' ').trim();
const yearOf=v=>Number(String(v?.year||v?.releaseInfo||v?.publishDate||v?.release_date||'').match(/(?:19|20)\d{2}/)?.[0]||0);
const imdbOf=v=>String(v?.imdbUrlRef||v?.imdbId||v?.imdb_id||v?.imdb||v?.id||'').match(/tt\d{5,12}/i)?.[0]?.toLowerCase()||'';
const titleOf=v=>String(v?.en_title||v?.title||v?.other_title||v?.ar_title||v?.name||'').trim();
const seasonOf=v=>Number(v?.season??v?.seasonNumber??v?.season_no??1)||1;
const episodeOf=v=>Number(v?.episodeNummer??v?.episodeNumber??v?.episode_no??v?.episode??1)||1;
const quality=v=>Number(String(v?.resolution??v??'').match(/(2160|1440|1080|720|576|480|360|240)/)?.[1]||0);
const goodUrl=v=>{let s=String(v||'').trim();if(s.startsWith('//'))s='https:'+s;return /^https?:\/\//i.test(s)?s:''};
async function cached(key,ttl,fn){const h=CACHE.get(key);if(h&&Date.now()-h.at<ttl)return h.v;const v=await fn();CACHE.set(key,{at:Date.now(),v});if(CACHE.size>1800)CACHE.delete(CACHE.keys().next().value);return v}
async function fetchJson(url,ms=9000){const c=new AbortController(),t=setTimeout(()=>c.abort(),ms);try{const r=await fetch(url,{signal:c.signal,headers:{'user-agent':UA,'accept':'application/json,*/*'}});if(!r.ok)throw new Error('http_'+r.status);return await r.json()}finally{clearTimeout(t)}}
async function cine(rel){return cached('cine:'+rel,120000,async()=>{let last;for(const h of HOSTS){try{return await fetchJson('https://'+h+'/api/android/'+String(rel).replace(/^\/+/,''),9000)}catch(e){last=e}}throw last||new Error('cinemana_unavailable')})}
const b64=s=>btoa(unescape(encodeURIComponent(String(s||''))));
const search=(kind,q,page=0,limit=24)=>cine('video/V/2/videoKind/'+kind+'/categoryNb/0/langNb/0/sortParam/desc/itemsPerPage/'+limit+'/video_title_search/'+encodeURIComponent(b64(q))+'/pageNumber/'+page+'/enableTranslation/0/level/1');
const info=id=>cine('allVideoInfo/id/'+encodeURIComponent(id));
const streams=id=>cine('transcoddedFiles/id/'+encodeURIComponent(id));
const episodes=id=>cine('videoSeason/id/'+encodeURIComponent(id));
async function cinemeta(type,id){return cached('cm:'+type+':'+id,21600000,async()=>{const j=await fetchJson('https://v3-cinemeta.strem.io/meta/'+type+'/'+id+'.json',8000);return j?.meta||null})}
async function cinemetaSearch(type,title,year){const k='cms:'+type+':'+clean(title)+':'+year;return cached(k,21600000,async()=>{const j=await fetchJson('https://v3-cinemeta.strem.io/catalog/'+type+'/top/search='+encodeURIComponent(title)+'.json',8000);const rows=asArray(j?.metas||j);const exact=rows.find(x=>clean(x?.name)===clean(title)&&(!year||yearOf(x)===Number(year)))||rows.find(x=>clean(x?.name)===clean(title))||rows[0];return exact?.id?.match(/^tt\d+$/i)?exact.id.toLowerCase():''})}
async function imdbForMember(m,type){const direct=String(m.imdb||'').match(/tt\d{5,12}/i)?.[0]?.toLowerCase();return direct||cinemetaSearch(type,m.title,m.year)}
async function resolveCinemana(type,imdb,season,episode){const kind=type==='series'?2:1,meta=await cinemeta(type,imdb).catch(()=>null),title=meta?.name||imdb,yr=yearOf(meta);const rows=[];for(const q of [title].filter(Boolean)){try{rows.push(...asArray(await search(kind,q,0,20)))}catch{}}
  let best=null,bestScore=-1;
  for(const x of rows){let s=0;const iid=imdbOf(x);if(iid)s=iid===imdb?500:-1000;const same=clean(titleOf(x))===clean(title);if(s<500&&same&&yr&&yearOf(x)===yr)s=100;else if(s<500&&same)s=50;if(s>bestScore){best=x;bestScore=s}}
  if(!best||bestScore<=0)return null;
  if(imdb&&!imdbOf(best)&&best?.nb){try{const full=await info(best.nb),obj=Array.isArray(full)?full[0]:full;const iid=imdbOf(obj);if(iid&&iid!==imdb&&bestScore<500)return null;if(iid===imdb)bestScore=500}catch{}}
  if(type!=='series'||!season||!episode)return best;
  const eps=asArray(await episodes(best.nb));return eps.find(e=>seasonOf(e)===Number(season)&&episodeOf(e)===Number(episode))||null}
async function manifest(){return {id:'com.mohammad.cinemana.stremio',version:'1.0.0',name:'Cinemana Collections',description:'Independent Cinemana catalogs, collections, franchises and direct streams.',types:['movie','series'],resources:['catalog',{name:'stream',types:['movie','series'],idPrefixes:['tt']}],catalogs:[...CATALOGS.map(c=>({type:c.type,id:c.id,name:c.title})),{type:'movie',id:'cine-search-movie',name:'بحث سينمانا — أفلام',extra:[{name:'search',isRequired:true}]},{type:'series',id:'cine-search-series',name:'بحث سينمانا — مسلسلات',extra:[{name:'search',isRequired:true}]}],behaviorHints:{configurable:false,p2p:false,adult:false}}}
async function catalog(type,id,extra){if(id==='cine-search-movie'||id==='cine-search-series'){const q=String(extra.search||'').trim();if(!q)return {metas:[]};const rows=asArray(await search(type==='series'?2:1,q,0,30));const metas=[];for(const x of rows.slice(0,30)){let iid=imdbOf(x);if(!iid&&x?.nb){try{iid=imdbOf(await info(x.nb))}catch{}}if(!iid)continue;metas.push({id:iid,type,name:titleOf(x)||iid,poster:x?.poster||x?.posterUrl||x?.imgMediumThumbObjUrl||x?.imgThumbObjUrl||('https://images.metahub.space/poster/medium/'+iid+'/img'),background:x?.imgObjUrl||('https://images.metahub.space/background/medium/'+iid+'/img'),releaseInfo:yearOf(x)?String(yearOf(x)):undefined})}return {metas}}
  const c=CATALOGS.find(x=>x.id===id&&x.type===type);if(!c)return {metas:[]};const metas=[];for(const m of c.members){const iid=await imdbForMember(m,type).catch(()=>'');if(!iid)continue;metas.push({id:iid,type,name:m.title,poster:'https://images.metahub.space/poster/medium/'+iid+'/img',background:'https://images.metahub.space/background/medium/'+iid+'/img',releaseInfo:m.year?String(m.year):undefined})}return {metas}}
async function stream(type,id){const raw=decodeURIComponent(String(id||'')),m=raw.match(/^(tt\d{5,12})(?::(\d+):(\d+))?$/i);if(!m)return {streams:[]};const iid=m[1].toLowerCase();if(type==='movie'&&Array.isArray(STATIC_MOVIE_STREAMS[iid])&&STATIC_MOVIE_STREAMS[iid].length){return {streams:STATIC_MOVIE_STREAMS[iid].map((x,i)=>({name:'Cinemana'+(quality(x)?' • '+quality(x)+'p':''),title:String(x?.resolution||('Source '+(i+1))),url:goodUrl(x.videoUrl),behaviorHints:{bingeGroup:'cinemana-direct'}})).filter(x=>x.url)}}const item=await resolveCinemana(type,iid,m[2],m[3]);if(!item?.nb)return {streams:[]};const rows=asArray(await streams(item.nb)).filter(x=>goodUrl(x?.videoUrl)).sort((a,b)=>quality(b)-quality(a));return {streams:rows.map((x,i)=>({name:'Cinemana'+(quality(x)?' • '+quality(x)+'p':''),title:String(x?.resolution||('Source '+(i+1))),url:goodUrl(x.videoUrl),behaviorHints:{bingeGroup:'cinemana-direct'}}))}}
function extras(seg){const o={};for(const p of decodeURIComponent(seg||'').split('&')){if(!p)continue;const i=p.indexOf('=');o[i<0?p:p.slice(0,i)]=decodeURIComponent(i<0?'':p.slice(i+1))}return o}
export default {async fetch(req){try{const u=new URL(req.url),p=u.pathname;if(req.method==='OPTIONS')return new Response('',{status:204,headers:{'access-control-allow-origin':'*','access-control-allow-headers':'*'}});if(p==='/'||p==='/index.html')return text('Cinemana Stremio Addon\nInstall /manifest.json in Stremio.\n');if(p==='/health')return json({ok:true,service:'cinemana-stremio',version:'1.0.0'});if(p==='/manifest.json')return json(await manifest());let m=p.match(/^\/catalog\/([^/]+)\/([^/]+)(?:\/([^/]+))?\.json$/);if(m)return json(await catalog(decodeURIComponent(m[1]),decodeURIComponent(m[2]),extras(m[3]||'')));m=p.match(/^\/stream\/([^/]+)\/(.+)\.json$/);if(m)return json(await stream(decodeURIComponent(m[1]),decodeURIComponent(m[2])));return json({error:'not_found'},404)}catch(e){return json({streams:[],metas:[],error:String(e?.message||e)})}}};
